const t = $('Tidy Deal Info').first().json;
const cur = 'USD';
const num = (v) => Number(String(v ?? '').replace(/[^0-9.\-]/g, '')) || 0;
const money = (n) => new Intl.NumberFormat('en-US', { style: 'currency', currency: cur }).format(n);
const fmt = (d) => { const x = DateTime.fromISO(String(d)); return x.isValid ? x.toFormat('d LLLL yyyy') : String(d ?? ''); };
const budget = num(t.budget);
const deposit = num(t.deposit) || Math.round(budget * 50) / 100;
const balance = Math.round((budget - deposit) * 100) / 100;
const pct = budget ? Math.round((deposit / budget) * 100) : 50;
const invoiceNumber = 'INV-' + String(t.id).replace(/^ONB-/, '');
const safe = String(t.name).replace(/[^A-Za-z0-9 ]/g, '').trim().replace(/ +/g, '-');
const today = $today.toISODate();
return [{ json: {
  deal_id: t.id,
  client_legal_name: t.name,
  contact_name: t.contact,
  contact_email: t.email,
  scope_items: t.scope,
  project_due_date: fmt(t.dueDate),
  total_amount: money(budget),
  deposit_amount: money(deposit),
  balance_due: money(balance),
  deposit_percent: pct + '%',
  invoice_number: invoiceNumber,
  invoice_date: fmt(today),
  agreement_date: fmt(today),
  due_date: fmt(DateTime.fromISO(today).plus({ days: 7 }).toISODate()),
  agreement_file: t.id + '_Agreement_' + safe,
  invoice_file: t.id + '_' + invoiceNumber + '_' + safe
} }];

