const f = $input.first().json;
// A realistic due date: at least MIN_DAYS from today and at most MAX_DAYS away.
const MIN_DAYS = 14;
const MAX_DAYS = 365;
const today = $today.startOf('day');
const earliest = today.plus({ days: MIN_DAYS });
const latest = today.plus({ days: MAX_DAYS });
const d = DateTime.fromISO(String(f['Due Date'] || ''));
let reason = '';
if (!d.isValid) reason = 'we could not read it';
else if (d < today) reason = 'it is in the past';
else if (d < earliest) reason = `we need at least ${MIN_DAYS} days to do the work properly`;
else if (d > latest) reason = 'it is more than a year away';
return [{ json: { ...f, dateOk: reason === '', dateReason: reason, chosenDate: d.isValid ? d.toFormat('d LLLL yyyy') : String(f['Due Date'] || ''), earliestDate: earliest.toFormat('d LLLL yyyy'), latestDate: latest.toFormat('d LLLL yyyy') } }];
